  // Rule: Render MUST NOT replace the todo list DOM nodes by removing and re-creating them.
  // Toggling a todo, toggle-all, or clear-completed MUST mutate existing nodes
  // in place so browser element references stay attached.
  "no-removechild-todolist": {
    description: "Render MUST mutate existing DOM nodes in place; todoList.removeChild in a while loop destroys element identity",
    check: (content, filePath) => {
      if (filePath !== 'js/app.js') return [];
      const violations = [];
      const lines = content.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const nextLine = lines[i + 1] || '';
        if (/todoList\.firstChild/.test(line) && /todoList\.removeChild/.test(nextLine)) {
          violations.push({ line: i + 1, file: filePath, detail: "while (todoList.firstChild) { todoList.removeChild(...) } destroys all child nodes; mutate existing nodes in place instead" });
        }
      }
      return violations;
    }
  },

  // Rule: Render MUST NOT be called from the blur event handler on edit inputs.
  // Calling render() from a blur handler destroys the editing node while the
  // browser event lifecycle is still processing it, causing a removeChild failure.
  "no-render-in-blur-handler": {
    description: "handleEditBlur must not call render(); blur event context may still reference the editing node",
    check: (content, filePath) => {
      if (filePath !== 'js/app.js') return [];
      const violations = [];
      const lines = content.split('\n');
      let inBlurHandler = false;
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (/function handleEditBlur/.test(line)) {
          inBlurHandler = true;
          continue;
        }
        if (inBlurHandler) {
          if (/^\s*\}/.test(line)) {
            inBlurHandler = false;
          } else if (/render\(\)/.test(line)) {
            violations.push({ line: i + 1, file: filePath, detail: "render() called inside handleEditBlur; use updateTodo directly instead" });
          }
        }
      }
      return violations;
    }
  }
};

